	try {
		redacted = redactDeepStrings(event);
	} catch {
		return null;
	}
	const sizeOf = (value) => {
		try {
			return JSON.stringify(value)?.length ?? Infinity;
		} catch {
			return Infinity;
		}
	};
	if (sizeOf(redacted) <= cap) return redacted;
