/***
 * MARK: executeIntegrationAssignment
 * @description Runs one leased `integrate` job (Step 4): merges
 *   `origin/<taskBranch>` into the target in an ephemeral detached worktree,
 *   CAS-pushes the target against the expected SHA, re-verifies, and reports.
 *   The task claim fences progress/logs/completion exactly like any stage;
 *   the integration lease serializes target writes. Outcomes:
 *   `landed` (merge pushed + verified → task completes passed with the
 *   integration payload the backend finalize needs), `conflict` (structured
 *   file list — never resolved here — task fails back visibly), or
 *   `stale-head` (a ref moved mid-lease → task fails with a retryable
 *   reason; the retry re-bases with fresh SHAs). The ephemeral worktree is
 *   removed in all outcomes.
 * @example await executeIntegrationAssignment({ config, client, logger, state, projectId: 'p', taskId: 't', claim, integration }) => { ... }
 ***/
/***
 * MARK: integrationMergeSubject
 * @description Subject for the integration merge commit. Integration always
 *   creates a real merge commit (--no-ff), even when the task branch could
 *   fast-forward: task work otherwise lands on the target as a chain of
 *   `kb/<id> … Runner stage output` commits, which the changelog filter
 *   (shared/changelogHistory/isAdminCommitSubject.js) hides as automation
 *   noise — so a merged, deployed feature never appeared in the in-app
 *   changelog (task a654a254, 2026-11-02). This subject matches none of the
 *   admin patterns, so the changelog shows one entry per merged task,
 *   carrying the task's own title.
 * @example integrationMergeSubject({ taskBranch: 'kb/abc', targetBranch: 'main', task: { title: 'Fix scroll' } }) => 'Merge kb/abc into main: Fix scroll'
 * @param {Object} opts - `{ taskBranch, targetBranch, task }`.
 * @returns {string} Single-line merge commit subject.
 ***/
export function integrationMergeSubject({ taskBranch, targetBranch, task } = {}) {
	const title = String(task?.title || task?.goal || "")
		.replace(/\s+/g, " ")
		.trim()
		.slice(0, 120);
	const base = `Merge ${taskBranch} into ${targetBranch}`;
	return title ? `${base}: ${title}` : base;
}

async function executeIntegrationAssignment({
	config,
	client,
	logger,
	state,
	projectId,
	taskId,
	claim,
	integration,
}) {
	const { taskBranch, expectedTaskSha, targetBranch, expectedTargetSha, mergeAttemptId } = integration;
	const integrationExecutionId = integration.integrationExecutionId;
	const integrationEpoch = integration.integrationEpoch;
	const runStartedAt = Date.now();
	const project = await client.getProject(projectId);
	const task = await client.getTask(projectId, taskId);
	const stageId = String(task.currentStageId ?? task.stages?.[0]?.id ?? "stage");
	const { executionId, epoch } = claim;
	state.executionId = executionId;
	state.epoch = epoch;
	state.session = null;
	const posture = formatPosture({ tiers: config.tiers, harness: "integration", model: null });
	const stopRenewal = startClaimRenewal({ client, logger, taskId, projectId, executionId, epoch });
	const integrationTimer = setInterval(() => {
		client
			.integrationHeartbeat({ projectId, targetBranch, executionId: integrationExecutionId, epoch: integrationEpoch })
			.catch((err) => {
				logger.warn(`Integration renewal failed: ${err?.message || err}`);
				if (err?.code === "STALE_EPOCH") clearInterval(integrationTimer);
			});
	}, CLAIM_HEARTBEAT_MS);
	if (typeof integrationTimer.unref === "function") integrationTimer.unref();

	let seq = 0;
	const sendLogs = async (bytes) => {
		for (const chunk of String(bytes).split("\n")) {
			if (!chunk) continue;
			await client.logs({ taskId, projectId, executionId, epoch, seq: seq++, bytes: chunk.slice(0, 4000) });
		}
	};
	const finishProgress = () =>
		client.progress({ taskId, projectId, executionId, epoch, stageId, event: "finished" }).catch(() => {});
	const failTask = (failureReason, extra = {}) =>
		client.complete({
			taskId, projectId, executionId, epoch,
			branch: taskBranch, outcome: "failed", failureReason,
			posture, durationMs: Date.now() - runStartedAt, ...extra,
		});

	try {
		await client.progress({ taskId, projectId, executionId, epoch, stageId, event: "started" });
		const { workdir, mirrorDir } = await prepareIntegrationWorkdir({
			repoUrl: project.gitUrl || project.repoUrl || null,
			workRoot: config.workRoot,
			taskBranch,
			expectedTaskSha,
			targetBranch,
			expectedTargetSha,
		});
		logger.log(`Integration workdir ${workdir} (ephemeral, detached at ${String(expectedTargetSha).slice(0, 7)}).`);
		try {
			try {
				await sendLogs(`[integrate] merging origin/${taskBranch} into ${targetBranch}`);
				await runGit(workdir, [
					"-c", "user.name=KainBain Integration",
					"-c", "user.email=kainbain-runner@local",
					"merge", "--no-ff", "-m", integrationMergeSubject({ taskBranch, targetBranch, task }),
					`origin/${taskBranch}`,
				]);
			} catch (mergeErr) {
				let conflicted = [];
				try {
					const { stdout } = await runGit(workdir, ["diff", "--name-only", "--diff-filter=U"]);
					conflicted = stdout.split("\n").map((l) => l.trim()).filter(Boolean);
				} catch {
					// Best effort: the file list below degrades to unknown.
				}
				try {
					await runGit(workdir, ["merge", "--abort"]);
				} catch {
					// Best effort: the tree may already be clean.
				}
				const looksLikeConflict =
					conflicted.length > 0 ||
					/CONFLICT|Automatic merge failed|unmerged/i.test(`${mergeErr?.message || ""}\n${mergeErr?.stderr || ""}`);
				if (!looksLikeConflict) throw mergeErr;
				const detail = `Merge conflicts in: ${conflicted.join(", ") || "unknown files"} — resolve on '${taskBranch}' and retry the merge stage`;
				await sendLogs(`[integrate] conflict: ${detail}`);
				await client.integrationReport({
					projectId, targetBranch, executionId: integrationExecutionId, epoch: integrationEpoch,
					outcome: "conflict", detail,
				}).catch(() => {});
				state.session = null; stopRenewal(); clearInterval(integrationTimer);
				await finishProgress();
				return await failTask(detail, { taskFiles: collectTaskFiles({ workdir, taskId }) });
			}
			const mergeSha = (await runGit(workdir, ["rev-parse", "HEAD"])).stdout.trim();
			try {
				await runGit(workdir, [
					"push", `--force-with-lease=${targetBranch}:${expectedTargetSha}`,
					"origin", `${mergeSha}:${targetBranch}`,
				]);
			} catch {
				const detail = `Target '${targetBranch}' moved during integration (CAS push pinned at ${String(expectedTargetSha).slice(0, 7)} rejected) — retry re-bases with fresh SHAs`;
				await sendLogs(`[integrate] stale-head: ${detail}`);
				await client.integrationReport({
					projectId, targetBranch, executionId: integrationExecutionId, epoch: integrationEpoch,
					outcome: "stale-head", detail,
				}).catch(() => {});
				state.session = null; stopRenewal(); clearInterval(integrationTimer);
				await finishProgress();
				return await failTask(detail);
			}
			await runGit(mirrorDir, ["fetch", "origin"]);
			const tip = (await runGit(mirrorDir, ["rev-parse", "--verify", `origin/${targetBranch}`])).stdout.trim();
			let ancestry = false;
			try {
				await runGit(mirrorDir, ["merge-base", "--is-ancestor", mergeSha, tip]);
				ancestry = true;
			} catch {
				ancestry = false;
			}
			await client.integrationReport({
				projectId, targetBranch, executionId: integrationExecutionId, epoch: integrationEpoch,
				outcome: "landed", mergeSha, detail: `merged '${taskBranch}' into '${targetBranch}'`,
			});
			state.session = null; stopRenewal(); clearInterval(integrationTimer);
			await finishProgress();
			if (ancestry) {
				await client.verifySha({ taskId, projectId, executionId, epoch, sha: mergeSha, present: true }).catch(() => {});
			}
			return await client.complete({
				taskId, projectId, executionId, epoch,
				sha: mergeSha, branch: taskBranch, outcome: "passed",
				posture, durationMs: Date.now() - runStartedAt,
				output: `[integrate] merged '${taskBranch}' into '${targetBranch}' (${mergeSha.slice(0, 7)})`,
				integration: {
					outcome: "landed", mergeSha, taskBranch, expectedTaskSha,
					targetBranch, expectedTargetSha, mergeAttemptId,
				},
			});
		} finally {
			await removeIntegrationWorkdir(mirrorDir, workdir);
		}
	} catch (err) {
		stopRenewal();
		clearInterval(integrationTimer);
		if (err?.code === "STALE_EPOCH") throw err;
		if (err instanceof RunnerGitError && err.code === "stale-head") {
			await client.integrationReport({
				projectId, targetBranch, executionId: integrationExecutionId, epoch: integrationEpoch,
				outcome: "stale-head", detail: err.message,
			}).catch(() => {});
			await finishProgress();
			return await failTask(`stale-head: ${err.message}`);
		}
		try {
			await client.interrupt({ taskId, projectId, executionId });
		} catch {
			// Interrupting is best-effort: the lease TTL still bounds the damage.
		}
		throw err;
	}
}

/***
 * MARK: runSingleAssignment
 * @description One explicit task assignment over the wire (ADR 0009 steps
 *   1–6, loopback): register (or poll a pending join until the human
 *   approves, then exit asking for the pasted credential), heartbeat,
 *   claim, load (clone/pull or adopt + per-task worktree), run the stage
 *   through the harness, stream sequenced logs, commit/push (push skipped
 *   `no-remote`), and complete with the SHA. Any failure after the claim
 *   interrupts the task so it re-queues as interrupted, never
 *   failed/complete. Orphaned workdirs are surfaced at boot (never deleted
 *   there); past the worktree cap the least-recently-used stale workdir is
 *   evicted on demand, and terminal tasks have their workdir reaped after
 *   the execution reports. Unpushed residue is always parked on
 *   kb-recovery/* first, never deleted.
 * @example await runSingleAssignment({ config, client, loadHarness }) => { executionId, epoch, sha }
 * @param {Object} opts - Options.
 * @param {Object} opts.config - Normalized runner config.
 * @param {Object} opts.client - Runner backend client.
 * @param {Function} [opts.loadHarness] - Harness loader (tests inject fakes).
 * @param {Object} [opts.logger] - Logger (defaults to console).
 * @returns {Promise<Object>} Execution summary.
 ***/
export async function runSingleAssignment({
	config,
	client,
	loadHarness = defaultLoadHarness,
	logger = console,
}) {
	resolveHarnessConfig(config);
	if (config.errors?.length) {
		throw new Error(`Invalid Runner config: ${config.errors.join(" ")}`);
	}
	const orphans = listOrphanWorkdirs(config.workRoot, config.taskId);
	if (orphans.length) {
		logger.warn(`Orphaned workdirs (left alone, may hold unpushed work): ${orphans.join(", ")}`);
		// Also surface this warning to the UI via the logs endpoint.
		try {
			await client.logs({
				taskId: config.taskId,
				projectId: config.projectId,
				executionId: "",
				epoch: 0,
				seq: 0,
				bytes: `WARN Orphaned workdirs: ${orphans.join(", ")}`.slice(0,4000),
			});
		} catch (e) {
			logger.warn(`Failed to send orphan warning to UI logs: ${e?.message || e}`);
		}
	}
	const state = { session: null, executionId: null, epoch: null };
	const { harness, stop } = await joinAndHeartbeat({ config, client, loadHarness, logger, state });
	try {
		const result = await executeAssignment({
			config,
			client,
			logger,
			harness,
			harnessId: config.harnessId,
			state,
			projectId: config.projectId,
			taskId: config.taskId,
		});
		// Terminal tasks never run again: reclaim their workdir slot now
		// instead of growing into the cap (best-effort, never throws).
		await reapTaskWorkdirIfTerminal({
			client,
			projectId: config.projectId,
			taskId: config.taskId,
			workRoot: config.workRoot,
		});
		return result;
	} finally {
		stop();
	}
}

/***
 * MARK: installRootFor
 * @description Resolves the self-update install root (Option A, ADR 0012):
 *   explicit KAINBAIN_RUNNER_INSTALL_ROOT wins, else a `runner-install`
 *   sibling of the work root (state lives with the installation, not with
 *   task worktrees).
 * @example installRootFor({ installRoot: '/opt/r' }) => '/opt/r'
 * @example installRootFor({ workRoot: 'runner-work' }) => '<abs>/runner-install'
 * @param {Object} [config] - Normalized runner config.
 * @returns {string} Install root path.
 ***/
export function installRootFor(config = {}) {
	const explicit = String(config.installRoot || "").trim();
	if (explicit) return explicit;
	return defaultInstallRoot({ workRoot: config.workRoot });
}

/***
 * MARK: maybeSelfUpdate
 * @description Idle-time self-update check (Option A, ADR 0012). No-ops
 *   unless auto-update is on AND the check interval has elapsed (jittered
 *   ±20% so a fleet does not thunder the release pointer). On a newer
 *   verified release, downloads, verifies, atomically stages it, and
 *   returns `applied` — the caller then exits 0 so the wrapper restarts
 *   into the new version. Any verification failure returns ok:false and
 *   keeps the current installation untouched.
 * @example await maybeSelfUpdate({ config, client }) => { checked: false, ... }
 * @param {Object} opts - Options (config, client?, logger?, installRoot?, now?, updateState?, updateDeps?, force?).
 *   `force` bypasses the interval gate for the 409 path, where the backend
 *   explicitly ordered an update — the Runner checks immediately instead of
 *   waiting out the jittered hour.
 * @returns {Promise<Object>} `{ checked, ok, update?, applied?, reason? }`. Apply
 *   failures are contained here (ok:false, failed status noted) and never throw.
 ***/
export async function maybeSelfUpdate({
	config,
	client = null,
	logger = console,
	installRoot = installRootFor(config),
	now = Date.now(),
	updateState = null,
	updateDeps = {},
	force = false,
} = {}) {
	if (!config?.autoUpdate) return { checked: false, reason: "auto-update disabled" };
	const interval = Number(config.updateCheckIntervalMs) || 3600000;
	const state = updateState || {};
	const last = Number(state.lastUpdateCheckAt) || 0;
	const jittered = interval * (0.8 + Math.random() * 0.4);
	if (!force && now - last < jittered) return { checked: false, reason: "interval" };
	state.lastUpdateCheckAt = now;
	const check = updateDeps.checkForUpdate || defaultCheckForUpdate;
	const apply = updateDeps.applyUpdate || defaultApplyUpdate;
	// Facts-only alert path (plan §4.5): the next heartbeat carries
	// updateStatus, which the backend stores on the runner record for the
	// fleet UI. No dedicated endpoint in v1.
	const note = (status) => {
		if (updateState && typeof updateState === "object") updateState.updateStatus = status;
	};
	const fail = (reason) => {
		logger.warn?.(`Runner update check failed: ${reason}`);
		note({ state: "failed", reason: String(reason || "unknown").slice(0, 500), at: new Date(now).toISOString() });
		return { checked: true, ok: false, reason: String(reason || "check failed") };
	};
	let result;
	try {
		result = await check({
			currentVersion: RUNNER_VERSION,
			updateUrl: config.updateUrl,
			logger,
		});
	} catch (err) {
		return fail(err?.message || err);
	}
	if (!result?.ok) return fail(result?.reason || "check failed");
	if (!result.update) return { checked: true, ok: true, update: null, reason: result.reason || "up to date" };
	logger.log?.(`Runner update available: ${result.update.version} (verified signature); staging install.`);
	// The install must stay untouched on ANY apply failure (network cut
	// mid-download, lock held, tar missing): contain it here so neither
	// the idle branch nor the 409 branch can crash the loop.
	let applied;
	try {
		applied = await apply({
			update: result.update,
			installRoot,
			updateUrl: config.updateUrl,
			logger,
		});
	} catch (err) {
		return fail(err?.message || err);
	}
	note({ state: "staged", version: result.update.version, at: new Date(now).toISOString() });
	return { checked: true, ok: true, update: result.update, applied };
}

/***
 * MARK: runDispatchLoop
 * @description Capability-aware dispatch loop (WP-3.1): joins and heartbeats
 *   exactly like a single assignment, then polls `POST /runners/dispatch`
 *   for backend-routed work until `dispatchIdleLimit` consecutive polls come
 *   back empty (`dispatchIdleLimit: 0` never idles out — the persistent
 *   service mode). Every poll is server-side scan → match → claim-fence, so
 *   concurrent loops never double-dispatch: a lost race surfaces as
 *   `CLAIM_CONFLICT` inside the fence and the loop simply polls again. A
 *   `STALE_RUNNER` answer triggers one fresh heartbeat and a single retry;
 *   `RUNNER_PAUSED` (operator-parked) backs off and re-polls until resumed;
 *   anything else throws loud.
 * @example await runDispatchLoop({ config, client }) => { assignments: 2, polls: 5 }
 * @param {Object} opts - Options.
 * @param {Object} opts.config - Normalized runner config (dispatch mode).
 * @param {Object} opts.client - Runner backend client.
 * @param {Function} [opts.loadHarness] - Harness loader (tests inject fakes).
 * @param {Object} [opts.logger] - Logger (defaults to console).
 * @returns {Promise<Object>} Loop summary (`assignments`, `polls`).
 ***/
export async function runDispatchLoop({
	config,
	client,
	loadHarness = defaultLoadHarness,
	logger = console,
}) {
	resolveHarnessConfig(config);
	if (config.errors?.length) {
		throw new Error(`Invalid Runner config: ${config.errors.join(" ")}`);
	}
	const orphans = listOrphanWorkdirs(config.workRoot, null);
	if (orphans.length) {
		logger.warn(`Orphaned workdirs (left alone, may hold unpushed work): ${orphans.join(", ")}`);
	}

	const state = { session: null, executionId: null, epoch: null };
	const { harness, harnesses, stop } = await joinAndHeartbeat({ config, client, loadHarness, logger, state });
	const idleLimit = config.dispatchIdleLimit ?? 3;
	const pollMs = config.dispatchPollMs ?? 5000;
	let assignments = 0;
	let polls = 0;
	try {
		for (let idle = 0; ;) {
			let answer;
			try {
				answer = await client.dispatchClaim({ projectIds: config.projectIds ?? null });
			} catch (err) {
				if (err?.code === "STALE_RUNNER") {
					await client.heartbeat({ runnerId: config.runnerId, facts: factsFor({ config, updateStatus: state?.updateStatus ?? null }) });
					answer = await client.dispatchClaim({ projectIds: config.projectIds ?? null });
				} else if (err?.statusCode === 429) {
					// D8 backpressure (ADR 0010): the fleet is at its
					// concurrency cap. Back off and re-poll WITHOUT
					// consuming idle budget — work exists, we just
					// may not take it yet.
					polls += 1;
					logger.log(`Dispatch: fleet busy (${err?.code ?? "capped"}); backing off.`);
					await new Promise((r) => setTimeout(r, pollMs));
					continue;
				} else if (err?.code === "RUNNER_PAUSED") {
					// Operator-parked: this Runner takes no new tasks until
					// resumed. Back off and re-poll WITHOUT consuming idle
					// budget — resuming picks the loop straight back up
					// with no restart.
					polls += 1;
					logger.log(`Dispatch: Runner paused by operator; backing off.`);
					await new Promise((r) => setTimeout(r, pollMs));
					continue;
				} else if (err?.code === "RUNNER_VERSION_BELOW_MINIMUM") {
					// Backend refuses dispatch below the minimum compatible
					// version (Option A, ADR 0012): self-update now (idle —
					// no active task), then exit 0 so the wrapper restarts
					// into the new version and re-registers. Forced: the
					// backend explicitly ordered the update, so the
					// interval gate is bypassed. No update available (or
					// a failed stage) means back off and poll again — the
					// loop never crashes on an update failure.
					polls += 1;
					logger.log(`Dispatch: below minimum version (${err?.message || "update required"}); updating.`);
					try {
						const upd = await maybeSelfUpdate({ config, client, logger, installRoot: installRootFor(config), updateState: state, force: true });
						if (upd?.applied) return { assignments, polls, updated: true, version: upd.update?.version };
					} catch (updateErr) {
						logger.warn?.(`Runner self-update failed (keeping current version): ${updateErr?.message || updateErr}`);
					}
					await new Promise((r) => setTimeout(r, pollMs));
					continue;
				} else {
					throw err;
				}
			}
			polls += 1;
			if (!answer.assigned) {
				// A busy integration slot is work waiting, not idleness:
				// back off WITHOUT consuming idle budget, like fleet
				// backpressure (D8) and operator pause.
				if (answer.code === "INTEGRATION_BUSY") {
					logger.log(`Dispatch: integration slot busy; backing off.`);
					await new Promise((r) => setTimeout(r, pollMs));
					continue;
				}
				idle += 1;
				// idleLimit 0 means a persistent service loop: never idle out.
				if (idleLimit > 0 && idle >= idleLimit) return { assignments, polls, idle: true };
				logger.log(
					`Dispatch: no work (${answer.code ?? "empty"}); idle ${idle}${idleLimit > 0 ? `/${idleLimit}` : "/∞ (persistent)"}.`,
				);
				// Self-update-on-idle (Option A, ADR 0012): the loop holds
				// no task here, so a staged update cannot strand work. A
				// staged update returns updated:true — the process exits 0
				// and the wrapper restarts into the new version.
				try {
					const upd = await maybeSelfUpdate({ config, client, logger, installRoot: installRootFor(config), updateState: state });
					if (upd?.applied) return { assignments, polls, idle, updated: true, version: upd.update?.version };
				} catch (err) {
					logger.warn?.(`Runner self-update failed (keeping current version): ${err?.message || err}`);
				}
				await new Promise((r) => setTimeout(r, pollMs));
				continue;
			}
			idle = 0;
			assignments += 1;
			// Multi-harness service: the dispatch answer names the
			// required harness (alias-resolved server-side) — serve with
			// that one, not the primary. An unloaded name falls back to
			// the primary with a warning: the lease is already fenced to
			// us, so stranding it would wedge the task, and the posture
			// line records what actually served.
			const wanted = answer.requirements?.harness || null;
			const servingId =
				wanted && harnesses[wanted] ? wanted : config.harnessId;
			if (wanted && !harnesses[wanted]) {
				logger.warn(
					`Requirements want harness '${wanted}' (not loaded); serving with primary '${servingId}'.`,
				);
			}
			await executeAssignment({
				config,
				client,
				logger,
				harness: harnesses[servingId] ?? harness,
				harnessId: servingId,
				state,
				projectId: answer.projectId,
				taskId: answer.taskId,
				lease: { executionId: answer.executionId, epoch: answer.epoch },
				backendPrompt: answer.prompt || "",
				kind: answer.kind || "",
				ciCommand: answer.command || "",
				runOnBranch: answer.runOnBranch || "",
				customBranch: answer.customBranch || "",
				ciTimeoutMs: Number(answer.timeoutMs) || 0,
				ciEnv: answer.env,
				// The backend already matched this task against our
				// advertised models: serve exactly its required model.
				model: answer.requirements?.model || null,
				// Leased integrations carry their target/task SHAs here;
				// executeAssignment routes `integrate` to the merge
				// procedure instead of a harness.
				integration: answer.integration ?? null,
			});
			// Terminal tasks never run again: reclaim their workdir slot
			// now instead of growing into the cap (best-effort, never
			// throws).
			await reapTaskWorkdirIfTerminal({
				client,
				projectId: answer.projectId,
				taskId: answer.taskId,
				workRoot: config.workRoot,
			});
		}
	} finally {
		stop();
	}
}

				files: request.body?.taskFiles,
			});
			const harnessId =
				runner.facts?.harnesses?.[0]?.id || request.body?.harnessId || "unknown";
			// Runner-run integration: the merge already landed via the
			// leased CAS push — verify read-only, freeze the baseline,
			// and advance. Never the generic stage finish.
			const project = projectStore.getProject(ctx.projectId);
			const allStages = resolveStagesForTask(project, live);
			const currentStage =
				allStages.find((s) => String(s?.id) === String(live?.currentStageId)) || allStages[0] || {};
			if (
				normalizeStageType(currentStage.type) === "merge" &&
				request.body?.integration?.outcome === "landed"
			) {
				const finish = await applyIntegrationReport({
					store: taskStore,
					projectStore,
					projectId: ctx.projectId,
					taskId: request.params.id,
					stage: currentStage,
					stages: allStages,
					integration: request.body.integration,
					runnerId: runner.runnerId,
				});
				return { ...receipt, ...finish };
			}
			// The Runner's explicit served-model field (new runners); normalized
			// through servingModelFor with the stage's kind so CI stages and the
			// "default" sentinel can never land in the report. Old runners omit
			// the field and applyRunnerReport falls back to the dispatch stamp.
			const reportedModelRef = servingModelFor({
				kind: normalizeStageType(currentStage.type),
				model: request.body?.model ?? null,
			});
			const finish = await applyRunnerReport({
				store: taskStore,
				projectStore,
				projectId: ctx.projectId,
				taskId: request.params.id,
				outcome: {
					status: outcome,
					output: request.body?.output ?? "",
					summary: request.body?.summary ?? "",
					modifiedFiles: request.body?.modifiedFiles ?? [],
					harnessId,
					modelRef: reportedModelRef,
					failureKind: request.body?.failureKind ?? null,
					failureReason: request.body?.failureReason ?? null,
					duration: request.body?.durationMs
						? String(Number(request.body.durationMs) / 1000)
						: "0.0",
					runnerId: runner.runnerId,
				},
			});
			return { ...receipt, ...finish };
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/tasks/:id/interrupt", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		const ctx = guardedTask(request, reply);
		if (!ctx) return;
		try {
			return executionLedger.interruptExecution({
				claimStore,
				taskStore,
				projectId: ctx.projectId,
				taskId: request.params.id,
				runnerId: runner.runnerId,
				executionId: request.body?.executionId ?? null,
				reason: request.body?.reason ?? null,
			});
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/tasks/:id/claim", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		const claimedRunnerId = request.body?.runnerId;
		if (
			claimedRunnerId &&
			claimedRunnerId !== runner.runnerId
		) {
			return reply.status(403).send({
				error: "Credential does not belong to the claimed Runner.",
				code: "SCOPE_MISMATCH",
			});
		}
		if (runner.paused === true) {
			return reply.status(409).send({
				error: `Runner ${runner.runnerId} is paused — resume it to take new tasks`,
				code: "RUNNER_PAUSED",
			});
		}
		// Runner self-update floor (Option A, ADR 0012): a known product
		// version below KAINBAIN_RUNNER_MIN_VERSION is refused so it cannot
		// mis-execute — the daemon self-updates on this code and retries.
		const belowMinimum = buildBelowMinimumRefusal({ runner, minVersion: config.runnerMinVersion });
		if (belowMinimum) return reply.status(409).send(belowMinimum);
		const projectId = resolveAndGuardProject(
			request.body?.projectId || request.query?.projectId,
			reply,
		);
		if (!projectId) return;
		const task = taskStore.getTask(projectId, request.params.id);
		if (!task) return reply.status(404).send({ error: "Task not found" });
		// Operator settings (System Settings › Runners) bind this direct
		// claim exactly like the dispatch scan: a Runner whose project is
		// unloaded, whose job-type switch is off, or whose tool subset
		// excludes the stage harness must not claim the task by asking for
		// it directly. Fail loud (409 + the verdict code) instead of
		// silently honouring a claim the operator switched off.
		const req = taskRequirements(projectStore.getProject(projectId) || {}, task);
		const claimVerdict = operatorConfigVerdict(runner, req, { projectId });
		if (!claimVerdict.ok) {
			return reply.status(409).send({
				error: `Runner ${runner.runnerId} settings refuse this task (${claimVerdict.reason}).`,
				code: claimVerdict.reason,
			});
		}
		// Stage runnerPolicy (stage settings allow/block list) binds this
		// direct claim exactly like the dispatch scan: claiming by task id
		// must not bypass a stage the Runner is not allowed on.
		const claimPolicyVerdict = stageRunnerPolicyVerdict(req.runnerPolicy, runner.runnerId);
		if (!claimPolicyVerdict.ok) {
			return reply.status(409).send({
				error: `Runner ${runner.runnerId} is refused by this stage's Runner list (${claimPolicyVerdict.reason}).`,
				code: claimPolicyVerdict.reason,
			});
		}
		try {
			const { executionId, epoch } = claimStore.claim(
				request.params.id,
				runner.runnerId,
				projectId,
			);
			// Same run attribution as the dispatch path: the requirement's
			// resolved harness/model names this run on the timeline/reports.
			const project = projectStore.getProject(projectId);
			const stages = resolveStagesForTask(project, task);
			const stage =
				stages.find((s) => String(s?.id) === String(task.currentStageId)) || stages[0] || null;
			stampDispatchRunAttribution({ taskStore, project, task, stage, stages, req });
			return { taskId: request.params.id, runnerId: runner.runnerId, executionId, epoch, ...await ciPayloadFor(projectId, task, null), prompt: curateRunnerPrompt({ project, task, stageId: task.currentStageId }) };
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/tasks/:id/claim-heartbeat", async (request, reply) => {
		// Lease renewal for long Runner executions (D1): the claim TTL
		// bounds a dead Runner's hold, so a live Runner must extend it
		// while the harness runs — otherwise the hold lapses mid-stage,
		// the task re-queues, and the finisher reports STALE_EPOCH.
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		const ctx = guardedTask(request, reply);
		if (!ctx) return;
		try {
			const hold = claimStore.describe(request.params.id);
			if (!hold || hold.runnerId !== runner.runnerId) {
				const err = new Error(
					`Stale execution for task ${request.params.id}: lease belongs to another Runner.`,
				);
				err.statusCode = 409;
				err.code = "STALE_EPOCH";
				throw err;
			}
			// Wall-clock stage timeout (no infinite renewal): a live Runner
			// renewing its lease forever must not outrun the stage budget —
			// otherwise a stuck harness sits claimed indefinitely and the
			// task reads frozen. On breach the hold is released and the
			// stage fails through the normal failure routing (retry/failback),
			// so the task re-queues instead of stranding.
			const project = projectStore.getProject(ctx.projectId);
			const stages = resolveStagesForTask(project, ctx.task);
			const stage =
				stages.find(
					(s) => String(s?.id) === String(ctx.task?.currentStageId),
				) || null;
			const timeoutMs = resolveStageTimeout(
				stage,
				stage?.type,
				config,
				project,
			);
			const { timedOut, elapsedMs } = runnerStageTimeoutStatus({
				startedAt: hold.startedAt ?? null,
				timeoutMs,
			});
			if (timedOut) {
				claimStore.invalidate(request.params.id);
				const reason =
					`Stage timed out after ${elapsedMs}ms (budget ${timeoutMs}ms) ` +
					`on stage '${stage?.name || stage?.id || ctx.task?.currentStageId}'.`;
				try {
					await applyRunnerReport({
						store: taskStore,
						projectStore,
						projectId: ctx.projectId,
						taskId: request.params.id,
						outcome: {
							status: "failed",
							output: "",
							harnessId: runner.facts?.harnesses?.[0]?.id || "unknown",
							failureKind: "timeout",
							failureReason: reason,
							duration: String(elapsedMs / 1000),
							runnerId: runner.runnerId,
						},
					});
				} catch {
					// The 409 below is the contract; a reporting failure must
					// never mask it (the zombie's late finish stays stale).
				}
				return reply.status(409).send({
					error: reason,
					code: "STAGE_TIMEOUT",
					timeoutMs,
					elapsedMs,
				});
			}
			const { epoch } = claimStore.heartbeat(
				request.params.id,
				request.body?.executionId,
			);
			return { taskId: request.params.id, runnerId: runner.runnerId, epoch };
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/runners/dispatch", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		if (!runnerRegistry.isFresh(runner)) {
			return reply.status(409).send({
				error: `Runner ${runner.runnerId} is stale — heartbeat, then ask again`,
				code: "STALE_RUNNER",
			});
		}
		// Parked Runners keep heartbeating (freshness is liveness, not
		// eligibility) but take no new work: fail fast here as well as in
		// the per-candidate match, so a paused fleet reads as paused and
		// not "no capable match".
		if (runner.paused === true) {
			return reply.status(409).send({
				error: `Runner ${runner.runnerId} is paused — resume it to take new tasks`,
				code: "RUNNER_PAUSED",
			});
		}
		// Runner self-update floor (Option A, ADR 0012): same refusal as
		// direct claim — shared helper so the two gates cannot drift.
		const belowMinimum = buildBelowMinimumRefusal({ runner, minVersion: config.runnerMinVersion });
		if (belowMinimum) return reply.status(409).send(belowMinimum);
		if (isTripped(taskStore)) {
			const circuit = circuitSnapshot(taskStore);
			return reply.status(409).send({
				error: "Engine is tripped — dispatch is stopped",
				tripped: true,
				reason: circuit.reason,
				source: circuit.source,
				trippedAt: circuit.trippedAt,
			});
		}
		const projectIds = Array.isArray(request.body?.projectIds)
			? request.body.projectIds
			: undefined;
		runnerRegistry.recordDispatchScope(runner.runnerId, projectIds);
		// D8 burn control (ADR 0010): the fleet cap stops parallel burn
		// before any scan; per-project caps skip that project's candidates
		// below. 0 disables that cap (default: single-Runner behaviour).
		const fleetCap = config.runnerMaxConcurrentFleet || 0;
		if (fleetCap > 0 && claimStore.countLiveHolds() >= fleetCap) {
			return reply.status(429).send({
				error: `Fleet at Runner concurrency cap (${fleetCap}); backing off.`,
				code: "FLEET_CONCURRENCY_EXHAUSTED",
			});
		}
		const projectCap = config.runnerMaxConcurrentPerProject || 0;
		const candidates = scanClaimableTasks(
			{ projectStore, taskStore, claimStore },
			{ projectIds, maxWaitMs: config.dispatchMaxWaitMs || 0 },
		);
		if (candidates.length === 0) {
			return { assigned: false, code: "NO_CLAIMABLE_TASKS" };
		}
		// A harness is dispatch-servable when some active, fresh Runner
		// advertises it. Alias targets on unserved harnesses are skipped
		// for this resolution (share redistributes, per the alias
		// contract); nothing served at all resolves null → loud miss.
		const isHarnessKnown = (name) =>
			runnerRegistry.records().some(
				(rec) =>
					rec?.status === "active" &&
					rec?.paused !== true &&
					runnerRegistry.isFresh(rec) &&
					(rec.capabilities?.harnesses || []).some((h) => h?.id === name),
			);
		const misses = {};
		for (const cand of candidates) {
			let req = cand.req;
			if (cand.req.alias) {
				const resolved = resolveAliasRequirement({
					project: projectStore.getProject(cand.projectId),
					aliasName: cand.req.alias,
					isHarnessKnown,
				});
				if (!resolved) {
					misses.ALIAS_UNRESOLVED = (misses.ALIAS_UNRESOLVED || 0) + 1;
					continue;
				}
				req = {
					...cand.req,
					harness: resolved.harness,
					model: resolved.model,
					alias: { name: resolved.aliasName, targetIndex: resolved.targetIndex },
				};
			}
			// The candidate's project travels alongside the requirements so
			// the operator project-scope check in `runnerMatches` can
			// refuse out-of-scope projects loudly (PROJECT_SCOPE) instead
			// of dispatching work the operator unloaded for this Runner.
			const verdict = runnerMatches(runner, req, {
				staleAfterMs: runnerRegistry.staleAfterMs,
				projectId: cand.projectId,
			});
			if (!verdict.ok) {
				misses[verdict.reason] = (misses[verdict.reason] || 0) + 1;
				continue;
			}
			if (
				projectCap > 0 &&
				claimStore.countLiveHolds({ projectId: cand.projectId }) >= projectCap
			) {
				misses.PROJECT_BUSY = (misses.PROJECT_BUSY || 0) + 1;
				continue;
			}
			// Merge stages dispatch as leased `integrate` jobs (Step 4): the
			// task claim fences progress/logs/completion exactly like any
			// stage, while the integration lease serializes target-branch
			// writes. A busy integration slot backs the Runner off to poll
			// again (the request stays queued — never lost, never doubled).
			if (req.kind === "merge") {
				let attempt;
				try {
					attempt = await prepareIntegrationAttempt({
						taskStore,
						projectStore,
						projectId: cand.projectId,
						task: cand.task,
					});
				} catch (err) {
					if (err?.code === "INTEGRATION_UNPREPARED") {
						misses.INTEGRATION_UNPREPARED = (misses.INTEGRATION_UNPREPARED || 0) + 1;
						continue;
					}
					return sendStoreError(reply, err);
				}
				let executionId;
				let epoch;
				try {
					({ executionId, epoch } = claimStore.claim(cand.taskId, runner.runnerId, cand.projectId));
				} catch (err) {
					if (err?.code === "CLAIM_CONFLICT") continue;
					return sendStoreError(reply, err);
				}
				if (!integrationQueue) {
					claimStore.invalidate(cand.taskId);
					misses.NO_INTEGRATION_QUEUE = (misses.NO_INTEGRATION_QUEUE || 0) + 1;
					continue;
				}
				integrationQueue.enqueue({
					projectId: cand.projectId,
					targetBranch: attempt.targetBranch,
					taskId: cand.taskId,
					taskBranch: attempt.taskBranch,
					expectedTaskSha: attempt.expectedTaskSha,
					expectedTargetSha: attempt.expectedTargetSha,
					mergeAttemptId: attempt.mergeAttemptId,
				});
				let lease;
				try {
					lease = integrationQueue.acquire({
						projectId: cand.projectId,
						targetBranch: attempt.targetBranch,
						runnerId: runner.runnerId,
					});
				} catch (err) {
					claimStore.invalidate(cand.taskId);
					if (err?.code === "INTEGRATION_BUSY") {
						return { assigned: false, code: "INTEGRATION_BUSY" };
					}
					return sendStoreError(reply, err);
				}
				if (!lease.leased) {
					claimStore.invalidate(cand.taskId);
					misses.INTEGRATION_EMPTY = (misses.INTEGRATION_EMPTY || 0) + 1;
					continue;
				}
				return {
					assigned: true,
					projectId: cand.projectId,
					taskId: cand.taskId,
					runnerId: runner.runnerId,
					executionId,
					epoch,
					stageId: cand.stage?.id ?? null,
					kind: "integrate",
					integration: {
						taskBranch: attempt.taskBranch,
						expectedTaskSha: attempt.expectedTaskSha,
						targetBranch: attempt.targetBranch,
						expectedTargetSha: attempt.expectedTargetSha,
						mergeAttemptId: attempt.mergeAttemptId,
						integrationExecutionId: lease.executionId,
						integrationEpoch: lease.epoch,
					},
					requirements: req,
				};
			}
			try {
				const { executionId, epoch } = claimStore.claim(
					cand.taskId,
					runner.runnerId,
					cand.projectId,
				);
				// Stamp the matched harness/model/alias onto the task so the
				// timeline and reports attribute THIS run (mirrors the
				// embedded dispatch stamp); CI/merge stamp nothing.
				const candProject = projectStore.getProject(cand.projectId);
				stampDispatchRunAttribution({
					taskStore,
					project: candProject,
					task: cand.task,
					stage: cand.stage,
					stages: resolveStagesForTask(candProject, cand.task),
					req,
				});
				return {
					assigned: true,
					projectId: cand.projectId,
					taskId: cand.taskId,
					runnerId: runner.runnerId,
					executionId,
					epoch,
					stageId: cand.stage?.id ?? null,
					prompt: curateRunnerPrompt({ project: candProject, task: cand.task, stageId: cand.stage?.id }),
					...await ciPayloadFor(cand.projectId, cand.task, cand.stage),
					requirements: req,
				};
			} catch (err) {
				if (err?.code === "CLAIM_CONFLICT") continue;
				return sendStoreError(reply, err);
			}
		}
		return { assigned: false, code: "NO_CAPABLE_MATCH", misses };
	});

	// ---- Integration leases (Step 3: serialized Runner-run merges) ---------
	// The backend never merges or pushes: it queues merge requests
	// (enqueue is backend-internal, called by the merge stage) and leases
	// the head entry to one Runner per project + target branch. The Runner
	// holds `executionId`/`epoch` exactly like a task claim; a superseded
	// report is stale by construction.
	app.post("/runners/integration/acquire", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		if (!integrationQueue) {
			return reply.status(503).send({ error: "Integration queue unavailable.", code: "NO_INTEGRATION_QUEUE" });
		}
		// Paused Runners take no new work on any route (mirrors the claim
		// and dispatch routes), and the operator's Runs-merges switch and
		// project scope bind this direct lease exactly like a dispatched
		// merge: acquiring a merge lease must not bypass Settings.
		if (runner.paused === true) {
			return reply.status(409).send({
				error: `Runner ${runner.runnerId} is paused — resume it to take new tasks`,
				code: "RUNNER_PAUSED",
			});
		}
		const mergeVerdict = operatorConfigVerdict(
			runner,
			{ kind: "merge" },
			{ projectId: request.body?.projectId },
		);
		if (!mergeVerdict.ok) {
			return reply.status(409).send({
				error: `Runner ${runner.runnerId} settings refuse merge work (${mergeVerdict.reason}).`,
				code: mergeVerdict.reason,
			});
		}
		// Stage runnerPolicy binds the direct merge lease exactly like a
		// dispatched merge: peek the head queued entry (the lease about to
		// be granted), resolve its task's stage, and refuse Runners the
		// stage does not allow. Anything unresolvable fails open to the
		// legacy lease — an empty queue still reports leased:false below.
		const acquireProjectId = request.body?.projectId;
		const acquireBranch = request.body?.targetBranch;
		if (acquireProjectId && acquireBranch) {
			const headEntry = integrationQueue.peekHead({ projectId: acquireProjectId, targetBranch: acquireBranch });
			if (headEntry?.taskId) {
				const headTask = taskStore.getTask(acquireProjectId, headEntry.taskId);
				if (!headTask) {
					// Task vanished (deleted while queued) — fall through to the
					// queue acquire; it will handle stale entries.
				} else {
					const headStages = resolveStagesForTask(projectStore.getProject(acquireProjectId), headTask);
					const headStage = (Array.isArray(headStages) ? headStages : []).find(
						(s) => String(s?.id) === String(headTask?.currentStageId),
					) || null;
					const leaseVerdict = stageRunnerPolicyVerdict(headStage, runner.runnerId);
					if (!leaseVerdict.ok) {
						return reply.status(409).send({
							error: `Runner ${runner.runnerId} is refused by this stage's Runner list (${leaseVerdict.reason}).`,
							code: leaseVerdict.reason,
						});
					}
				}
			}
		}
		try {
			return integrationQueue.acquire({
				projectId: request.body?.projectId,
				targetBranch: request.body?.targetBranch,
				runnerId: runner.runnerId,
			});
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/runners/integration/heartbeat", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		if (!integrationQueue) {
			return reply.status(503).send({ error: "Integration queue unavailable.", code: "NO_INTEGRATION_QUEUE" });
		}
		try {
			return integrationQueue.heartbeat({
				projectId: request.body?.projectId,
				targetBranch: request.body?.targetBranch,
				executionId: request.body?.executionId,
				epoch: request.body?.epoch,
			});
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/runners/integration/report", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		if (!integrationQueue) {
			return reply.status(503).send({ error: "Integration queue unavailable.", code: "NO_INTEGRATION_QUEUE" });
		}
		try {
			const receipt = integrationQueue.report({
				projectId: request.body?.projectId,
				targetBranch: request.body?.targetBranch,
				executionId: request.body?.executionId,
				epoch: request.body?.epoch,
				outcome: request.body?.outcome,
				mergeSha: request.body?.mergeSha ?? null,
				detail: request.body?.detail ?? null,
			});
			return { ...receipt, runnerId: runner.runnerId };
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.get("/runners/integration", async (request) => {
		if (!integrationQueue) return { depth: 0, lease: null, counters: {} };
		return {
			...integrationQueue.describe({
				projectId: request.query?.projectId,
				targetBranch: request.query?.targetBranch,
			}),
			counters: integrationQueue.snapshot(),
		};
	});

	// ---- Steering acks (D5, ADR 0011) --------------------------------------
	// The unified POST /tasks/:id/steer (taskFlowRoutes) queues against the
	// live lease; the Runner pulls on heartbeat and acks here.
	app.post("/tasks/:id/steer-ack", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		const ctx = guardedTask(request, reply);
		if (!ctx) return;
		try {
			const hold = claimStore.describe(request.params.id);
			if (
				!hold ||
				hold.executionId !== request.body?.executionId ||
				hold.epoch !== request.body?.epoch ||
				hold.runnerId !== runner.runnerId
			) {
				return reply.status(409).send({
					error: `Ack targets a superseded execution (no matching live lease).`,
					code: "STALE_EPOCH",
				});
			}
			return steerStore.ack(request.body.executionId, request.body?.steerId, {
				ok: request.body?.ok,
				detail: request.body?.detail,
			});
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.get("/tasks/:id/steers", async (request, reply) => {
		const ctx = guardedTask(request, reply);
		if (!ctx) return;
		const executionId = request.query?.executionId;
		if (!executionId || typeof executionId !== "string") {
			return reply.status(400).send({
				error: "steers requires an executionId query.",
				code: "INVALID_STEER_ARGS",
			});
		}
		return {
			taskId: request.params.id,
			executionId,
			pending: steerStore.pendingFor(executionId),
			receipts: steerStore.receiptsFor(executionId),
		};
	});
};
